.fast-simon-autocomplete.horizontal .fs-product {
    flex-direction: row;
    align-items: center;
    border: unset;
}
.fast-simon-autocomplete {
    min-width: unset !important;
    max-width: 90% !important;
    width: 100% !important;
    left: 50% !important;
    transform: translate(-50%,0);

}

.fast-simon-autocomplete.horizontal  .fast-horizontal-container {
    grid-template-columns: 350px auto;
    padding: 0 20px;
}
.products.fast-horizontal-products{
    order: 2;
    grid-template-columns: 1fr 1fr !important;
}
.fast-simon-autocomplete.horizontal .fs-product .fs-product-image {
    min-height: auto;
    width: 85px;
}
.fast-horizontal-products .info.fs-product-info {
    margin-left: 10px;
}  
.fast-horizontal-products .info.fs-product-info .fs-product-title,
.children.single-line .fs-product-title {
    color: #000 !important;
    font-weight: 400 !important;

}
.fast-horizontal-products .info.fs-product-info .fs-product-title strong,
.children.single-line .fs-product-title strong{
    text-decoration: none !important;
    font-weight: 400 !important;
}
.fast-simon-autocomplete .summery {
    padding: 15px;
    font-size: 16px;
    line-height: 1;
    display: block;
    max-width: calc(100% - 405px);
    text-align: left;
    width: 100%;
    margin-left: auto;
}
.fast-simon-autocomplete .fs-autocomplete-header svg,
.fast-simon-autocomplete .triangle.fs-triangle,
.fast-simon-autocomplete .autocomplete-inner .fs-turbolink-list{
  display: none !important;
}
.fast-simon-autocomplete .children .fast-ac-item.fs-product,
.fast-simon-autocomplete .fs-autocomplete-header{
    border: unset !important;  
    align-items: center; 
}
.fast-horizontal-container .items.fast-horizontal-items {
    border-right: 1px solid gray;
}
.fast-horizontal-container .fs-popular-searches-list,
.products.fast-horizontal-products{
    padding: 15px 0;
}  
.autocomplete.horizontal .autocomplete-inner{
  padding:0 8px;
}
.compareExist.fs-product-price-wrapper {
  display: flex;
  flex-direction: row-reverse;
  justify-content: flex-end;
}  
.compareExist.fs-product-price-wrapper .compare {
  margin-right: 5px;
}
.compareExist.fs-product-price-wrapper span:not(.compare){
  color: red;
}
@media only screen and (min-width: 1450px){
  .fast-simon-autocomplete {
    max-width: 1400px !important;
  } 
}
@media only screen and (max-width:992px) {
  /* .fast-simon-autocomplete .autocomplete-inner {
      grid-template-columns: 1fr 1fr;
  } */
  .fast-horizontal-container .items.fast-horizontal-items {
      border-right: none;
  }
  .fast-simon-autocomplete .autocomplete-inner .children.inline{
      flex-direction: column;
      justify-content: start;
      align-items: self-start !important;
  }
  .fast-simon-autocomplete .autocomplete-inner .children.inline .line-item.bubble{
      background-color: transparent;
      font-weight: 400;
      padding: 0 5px;
  }
  .fast-simon-autocomplete .autocomplete-inner .fs-popular-searches-list,
  .items.fast-horizontal-items{
    order:2;
  }


  .fast-simon-autocomplete .fs-product-list .fs-autocomplete-header,
  .fast-simon-autocomplete.fast-simon-autocomplete .summery{
      display: none !important;
  }
  .fast-simon-autocomplete .fs-product-list,
  .products.fast-horizontal-products{
      padding: 15px 10px 30px 10px;
  }
  .fast-simon-autocomplete {
      max-width: 80% !important;
      box-shadow: unset !important;
      border: 1px solid #000;
      border-top: 2px solid #000 !important;
  }
  .fast-simon-autocomplete.horizontal .fast-horizontal-container {
      grid-template-columns: 100%;
  }
  .info.fs-ac-18sj0w9 {
      margin-left: 10px !important;
  }

}
@media only screen and (max-width:800px) {
  .autocomplete.list {
      transform: translate(11.6%,0);
  }
  .fast-simon-autocomplete .autocomplete-inner{
      max-height: 70vh !important;
      display: flex !important;
      flex-direction: column;
      height: 100%;
  }
  .fast-simon-autocomplete .fs-product-list{
    overflow: auto;
  }
  .fast-simon-autocomplete .autocomplete-inner .fs-popular-searches-list{
     flex: 1;
  }
  .children.single-line .fs-product-title,
  .price.fs-product-price-wrapper .fs-price{
      font-size: 14px;
  }
}
@media only screen and (max-width:767px) {
  .children.single-line {
      grid-template-columns: unset;
  }
}
@media only screen and (max-width:375px) {  
  .fast-simon-autocomplete .fast-ac-item.fs-product .image {
      display: none;
  }
  .children.single-line a.fast-ac-item.fs-product.item {
      grid-template-columns: 100%;
  }
}
